"""Generate Dart character classes from the UCD's extracted/DerivedBidiClass.txt.

Usage: python3 tool/generate_bidi_classes.py /path/to/DerivedBidiClass.txt
"""
from itertools import groupby
from pathlib import Path
import re
import sys


source = Path(sys.argv[1]).read_text(encoding="utf-8")
version = re.match(r"# DerivedBidiClass-([\d.]+)\.txt", source)[1]
classes = bytearray(0x110000)


def assign(interval, name):
    bounds = interval.split("..")
    first, last = int(bounds[0], 16), int(bounds[-1], 16)
    value = 1 if name in {"L", "Left_To_Right"} else 2 if name in {
        "R", "AL", "Right_To_Left", "Arabic_Letter"
    } else 0
    classes[first:last + 1] = bytes([value]) * (last - first + 1)


# More specific @missing defaults override the global default. Explicit
# entries, including neutral emoji and marks, override all defaults.
for interval, name in re.findall(r"# @missing: ([\dA-F.]+); (\w+)", source):
    assign(interval, name)
for interval, name in re.findall(r"^([\dA-F.]+)\s*; (\w+)", source, re.M):
    assign(interval, name)

patterns = {1: [], 2: []}
offset = 0
for value, group in groupby(classes):
    end = offset + sum(1 for _ in group) - 1
    if value in patterns:
        pattern = rf"\u{{{offset:X}}}"
        if end != offset:
            pattern += rf"-\u{{{end:X}}}"
        patterns[value].append(pattern)
    offset = end + 1

lines = [
    f"// Generated by tool/generate_bidi_classes.py from Unicode {version}.",
    f"// https://www.unicode.org/Public/{version}/ucd/extracted/DerivedBidiClass.txt",
    "// Copyright Unicode, Inc. See THIRD_PARTY_NOTICES.md.",
]
for value, name in [(1, "ltrCharacters"), (2, "rtlCharacters")]:
    lines += ["", f"const {name} ="]
    chunk = ""
    for interval in patterns[value]:
        if len(chunk + interval) > 65:
            lines.append(f"    r'{chunk}'")
            chunk = ""
        chunk += interval
    lines.append(f"    r'{chunk}';")

output = Path(__file__).resolve().parents[1] / "lib/src/flutter/render/bidi_classes.dart"
output.write_text("\n".join(lines) + "\n", encoding="utf-8")
